+                .field("stopwords1")
+                .zeroTermsQuery(zeroTermsQuery))
+            .toQuery(context);
+        expected = new BooleanQuery.Builder()
+            .add(expectedEmptyQuery, BooleanClause.Occur.SHOULD)
+            .build();
+        assertEquals(expected, query);
+
+        query = new BoolQueryBuilder()
