+                .addField("a", (float) boost1)
+                .addField("b", (float) boost2)
+                .addTerm(new BytesRef("foo"))
+                .addTerm(new BytesRef("bar"))
+                .build();
+
+        checkExpectedHits(searcher, numMatch, query, new TermQuery(new Term("ab", "foo")));
+
+        reader.close();
+        w.close();
