+        TopScoreDocCollector firstCollector =
+            TopScoreDocCollector.create(numHits, null, Integer.MAX_VALUE);
+        searcher.search(firstQuery, firstCollector);
+        TopDocs firstTopDocs = firstCollector.topDocs();
