+        searcher.search(secondQuery, secondCollector);
+        TopDocs secondTopDocs = secondCollector.topDocs();
+        CheckHits.checkEqual(firstQuery, secondTopDocs.scoreDocs, firstTopDocs.scoreDocs);
+    }
